from rdkit import Chem
from rdkit.Chem import AllChem
from rdkit.Geometry import Point3D
base=Chem.MolFromSmiles('Cc1c[nH]c2ccccc12')
root=Chem.RWMol()
for j in range(6):
  for atom in base.GetAtoms():
    a=Chem.Atom(atom); a.SetNoImplicit(False)
    if a.GetSymbol()=='N':a.SetNumExplicitHs(0);a.SetNoImplicit(True)
    root.AddAtom(a)
  for bond in base.GetBonds():root.AddBond(10*j+bond.GetBeginAtomIdx(),10*j+bond.GetEndAtomIdx(),bond.GetBondType())
for j in range(2):
 si=root.AddAtom(Chem.Atom('Si'))
 for k in range(3):root.AddBond(si,10*(3*j+k)+3,Chem.BondType.SINGLE)
au=Chem.Atom('Au');au.SetFormalCharge(-1);idx=root.AddAtom(au)
for j in range(2):root.AddBond(60+j,idx,Chem.BondType.SINGLE)
m=root.GetMol()
try: Chem.SanitizeMol(m);print(Chem.MolToSmiles(m))
except Exception as e: print('sanitize',e)
m=Chem.AddHs(m)
print('count',m.GetNumAtoms(),'UFF parameter?',AllChem.UFFHasAllMoleculeParams(m),'MMFF?',AllChem.MMFFHasAllMoleculeParams(m))
res=AllChem.EmbedMolecule(m,randomSeed=39,maxAttempts=300,useRandomCoords=True)
print('embed',res,flush=True)
if res==0:
 try: print('uff',AllChem.UFFOptimizeMolecule(m,maxIters=600),flush=True)
 except Exception as ex:print('uff fail',ex)
 with open('start.xyz','w') as out:
  out.write(str(m.GetNumAtoms())+'\nBis(tris(3-methylindolyl)silyl)gold anion\n')
  for a in m.GetAtoms():
   p=m.GetConformer().GetAtomPosition(a.GetIdx());out.write(f'{a.GetSymbol():2s} {p.x:.7f} {p.y:.7f} {p.z:.7f}\n')
PY
